script:
(function () {
  'use strict';
  // 365/365 daily simple interest loan with payments made early, late, missed or for other amounts.
  //   Interest for a period = principal x rate x days / 365 (365/365), or with "actual/actual" the days
  //   falling in a leap year are divided by 366. Interest is charged on principal only (simple interest):
  //   a payment pays the interest owed first, the rest reduces principal; interest it does not cover is
  //   carried as unpaid interest that never earns interest itself.
  //   Payment k is due on the first due date + (k - 1) months (day clamped to the month's end); a
  //   changed payment is made on its due date + the days entered. The last payment (or any earlier
  //   payment big enough) pays off principal plus all interest owed.
  //   Regular payment: by default, the payment (rounded to the cent) that leaves a final payment equal
  //   to it when every payment is on time, found by bisection on the on-schedule simulation.
  // Dates are whole day numbers from YYYY-MM-DD (H. Hinnant's days_from_civil), so time zones can't shift a day.
  // Checked in Node (scratchpad tests/w3b6_loans/d35.test.js): 31 days on $100,000 at 6% = $509.59;
  //   with funding exactly one 365-day year apart the 365/365 interest equals rate x principal; a
  //   $25,000, 8%, 60-payment loan funded Jan 15 2026 gives a regular payment within 1% of the
  //   rate/12 formula ($506.88 vs $506.91) and a final payment of $506.93; an independent Python
  //   day-by-day replica (tests/w3b6_loans/d35_replica.py) matches total interest $5,412.85 and the
  //   final payment to the cent; paying payment 3 fifteen days late costs $2.01 net (that period
  //   carries ~$80 more interest, the next one ~$78 less); 0% rate gives no interest and loan / n payments; a missed
  //   payment carries unpaid interest without compounding; leap-year (actual/actual) totals are lower
  //   than 365/365 over a span containing Feb 29.
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var MAX_ROWS = 24, rowCounter = 0, last = null, firstTouched = false;
  var DEFAULT_ROWS = [{ n: 3, shift: 15, amount: '' }, { n: 8, shift: -10, amount: '1500' }];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var INPUT_CLASS = 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none';

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function parse(raw) {
    raw = String(raw === undefined || raw === null ? '' : raw).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function read(id) { return parse(el(id).value); }

  // ---- Dates ----
  function daysFromCivil(y, m, d) {
    y -= m <= 2 ? 1 : 0;
    var era = Math.floor(y / 400), yoe = y - era * 400;
    var doy = Math.floor((153 * ((m + 9) % 12) + 2) / 5) + d - 1;
    var doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    return era * 146097 + doe - 719468;
  }
  function civilFromDays(z) {
    z += 719468;
    var era = Math.floor(z / 146097), doe = z - era * 146097;
    var yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
    var doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
    var mp = Math.floor((5 * doy + 2) / 153);
    var d = doy - Math.floor((153 * mp + 2) / 5) + 1, m = mp < 10 ? mp + 3 : mp - 9;
    return { y: yoe + era * 400 + (m <= 2 ? 1 : 0), m: m, d: d };
  }
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || '').trim());
    if (!m) return NaN;
    var y = +m[1], mo = +m[2], d = +m[3];
    if (mo < 1 || mo > 12 || d < 1 || d > 31) return NaN;
    var z = daysFromCivil(y, mo, d), c = civilFromDays(z);
    return c.y === y && c.m === mo && c.d === d ? z : NaN;
  }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function iso(z) { var c = civilFromDays(z); return c.y + '-' + pad(c.m) + '-' + pad(c.d); }
  function fmt(z) { var c = civilFromDays(z); return MONTHS[c.m - 1] + ' ' + c.d + ', ' + c.y; }
  function daysInMonth(y, m) { return daysFromCivil(m === 12 ? y + 1 : y, m === 12 ? 1 : m + 1, 1) - daysFromCivil(y, m, 1); }
  function addMonths(z, k) {
    var c = civilFromDays(z), t = (c.m - 1) + k, y = c.y + Math.floor(t / 12), m = ((t % 12) + 12) % 12 + 1;
    return daysFromCivil(y, m, Math.min(c.d, daysInMonth(y, m)));
  }

  // ---- Maths ----
  // Fraction of a year between day numbers a and b.
  function yearFraction(a, b, basis) {
    if (b <= a) return 0;
    if (basis !== 'actual') return (b - a) / 365;
    var total = 0, x = a;
    while (x < b) {
      var y = civilFromDays(x).y, startY = daysFromCivil(y, 1, 1), next = daysFromCivil(y + 1, 1, 1), end = Math.min(b, next);
      total += (end - x) / (next - startY);
      x = end;
    }
    return total;
  }

  // changes: { n: { shift: days, amount: number|NaN } }
  function simulate(loan, rate, pay, n, start, first, basis, changes) {
    var bal = loan, unpaid = 0, prev = start, rows = [], totalInterest = 0, totalPaid = 0;
    for (var k = 1; k <= n; k++) {
      var due = addMonths(first, k - 1), ch = changes && changes[k], date = due + (ch ? ch.shift : 0);
      var interest = bal * rate * yearFraction(prev, date, basis);
      var owed = unpaid + interest, amount = ch && !isNaN(ch.amount) ? ch.amount : pay, principal;
      if (k === n || amount >= bal + owed - 0.005) {
        amount = bal + owed; principal = bal; bal = 0; unpaid = 0;
      } else {
        var toInterest = Math.min(amount, owed);
        unpaid = owed - toInterest; principal = amount - toInterest; bal -= principal;
        if (unpaid < 1e-9) unpaid = 0;
      }
      totalInterest += interest; totalPaid += amount;
      rows.push({ n: k, due: due, date: date, days: date - prev, payment: amount, interest: interest, principal: principal,
        unpaid: unpaid, balance: bal, change: ch || null });
      prev = date;
      if (bal === 0) break;
    }
    var lastRow = rows[rows.length - 1];
    return { rows: rows, interest: totalInterest, paid: totalPaid, finalPayment: lastRow.payment, finalDate: lastRow.date, count: rows.length };
  }

  // Payment (to the cent) that pays the loan off on schedule when every payment is on time.
  function levelPayment(loan, rate, n, start, first, basis) {
    if (n === 1) return Math.round(simulate(loan, rate, 0, 1, start, first, basis, null).finalPayment * 100) / 100;
    var lo = 0, hi = loan * (1 + rate * yearFraction(start, addMonths(first, n - 1), basis)) + 1;
    for (var it = 0; it < 100; it++) {
      var mid = (lo + hi) / 2, s = simulate(loan, rate, mid, n, start, first, basis, null);
      if (s.count === n && s.finalPayment > mid) lo = mid; else hi = mid;
    }
    return Math.round((lo + hi) / 2 * 100) / 100;
  }

  // ---- Payment change rows (DOM methods only) ----
  function make(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }
  function numberField(id, label, value, affix, affixFirst, attrs) {
    var wrap = make('div'), lab = make('label', 'form-label', label), group = make('div', 'input-group'), input = make('input', INPUT_CLASS);
    lab.setAttribute('for', id);
    input.type = 'number'; input.id = id;
    Object.keys(attrs).forEach(function (k) { input.setAttribute(k, attrs[k]); });
    input.value = value === undefined || value === null ? '' : String(value);
    var a = make('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }
  function addRow(d) {
    var list = el('d35Rows');
    if (list.querySelectorAll('[data-row]').length >= MAX_ROWS) return;
    rowCounter++;
    var id = rowCounter, row = make('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-row', String(id));
    var head = make('div', 'flex items-center justify-between gap-3');
    var title = make('p', 'text-sm font-semibold text-ink', 'Changed payment');
    title.setAttribute('data-row-title', '');
    var remove = make('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () { row.remove(); refreshRows(); update(); });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);
    var grid = make('div', 'form-row form-row-3');
    grid.appendChild(numberField('d35N' + id, 'Payment number', d.n, '#', true, { min: '1', step: '1', inputmode: 'numeric' }));
    grid.appendChild(numberField('d35Shift' + id, 'Days early or late', d.shift, 'days', false, { step: '1', inputmode: 'numeric' }));
    grid.appendChild(numberField('d35Amt' + id, 'Amount paid', d.amount, '$', true, { min: '0', step: '1', inputmode: 'decimal', placeholder: 'Regular' }));
    row.appendChild(grid);
    list.appendChild(row);
    refreshRows();
  }
  function refreshRows() {
    var rows = el('d35Rows').querySelectorAll('[data-row]');
    for (var i = 0; i < rows.length; i++) {
      rows[i].querySelector('[data-row-title]').textContent = 'Changed payment ' + (i + 1);
      rows[i].querySelector('[data-remove]').setAttribute('aria-label', 'Remove changed payment ' + (i + 1));
    }
    el('d35Add').disabled = rows.length >= MAX_ROWS;
  }
  function readChanges(n) {
    var rows = el('d35Rows').querySelectorAll('[data-row]'), changes = {}, err = '', count = 0;
    for (var i = 0; i < rows.length && !err; i++) {
      var id = rows[i].getAttribute('data-row'), label = 'Changed payment ' + (i + 1) + ': ';
      var rawN = String(el('d35N' + id).value).trim(), rawS = String(el('d35Shift' + id).value).trim(), rawA = String(el('d35Amt' + id).value).trim();
      if (rawN === '' && rawS === '' && rawA === '') continue;
      var k = parse(rawN), shift = rawS === '' ? 0 : parse(rawS), amount = rawA === '' ? NaN : parse(rawA);
      if (isNaN(k) || k < 1 || k > n || k % 1 !== 0) err = label + 'enter a payment number from 1 to ' + n + '.';
      else if (changes[k]) err = label + 'payment ' + k + ' is already changed above.';
      else if (isNaN(shift) || shift % 1 !== 0 || shift < -180 || shift > 365) err = label + 'enter whole days from -180 (early) to 365 (late).';
      else if (rawA !== '' && (isNaN(amount) || amount < 0 || amount > 1e10)) err = label + 'the amount can\'t be negative.';
      else { changes[k] = { shift: shift, amount: amount }; count++; }
    }
    return { changes: changes, error: err, count: count };
  }

  // ---- Output ----
  function signed(x) {
    if (Math.abs(x) < 0.005) return money.format(0);
    return (x > 0 ? '+' : '−') + money.format(Math.abs(x));
  }
  function mark(r) {
    var c = r.change;
    if (!c) return '';
    if (!isNaN(c.amount) && c.amount === 0) return ' (missed)';
    var bits = [];
    if (c.shift > 0) bits.push(c.shift + ' day' + (c.shift === 1 ? '' : 's') + ' late');
    if (c.shift < 0) bits.push(-c.shift + ' day' + (c.shift === -1 ? '' : 's') + ' early');
    if (!isNaN(c.amount)) bits.push('amount changed');
    return bits.length ? ' (' + bits.join(', ') + ')' : '';
  }
  function renderSchedule() {
    var body = el('d35Schedule');
    if (!last) { body.innerHTML = ''; return; }
    var s = el('d35View').value === 'base' ? last.base : last.yours;
    body.innerHTML = s.rows.map(function (r) {
      return '<tr><td>' + r.n + '</td><td>' + fmt(r.due) + '</td><td>' + fmt(r.date) + mark(r) + '</td><td>' + r.days + '</td><td>' +
        money.format(r.payment) + '</td><td>' + money.format(r.interest) + '</td><td>' + money.format(r.principal) + '</td><td>' +
        money.format(r.unpaid) + '</td><td>' + money.format(r.balance) + '</td></tr>';
    }).join('');
  }
  function clear() {
    ['d35Payment', 'd35Diff', 'd35Final', 'd35PerDiem', 'd35Summary'].forEach(function (id) { setText(id, '–'); });
    el('d35Compare').innerHTML = '';
    last = null;
    renderSchedule();
  }

  function update(e) {
    var target = e && e.target ? e.target.id : '';
    if (target === 'd35First') firstTouched = true;
    var start = parseDate(el('d35Start').value);
    if (target === 'd35Start' && !firstTouched && !isNaN(start)) el('d35First').value = iso(addMonths(start, 1));
    var first = parseDate(el('d35First').value);
    var loan = read('d35Loan'), rate = read('d35Rate'), n = read('d35Term'), payRaw = String(el('d35Pay').value).trim();
    var payIn = payRaw === '' ? NaN : parse(payRaw), basis = el('d35Basis').value;
    var err = el('d35Error'), msg = '', ch = null;
    if ([loan, rate, n].some(isNaN)) msg = 'Enter the loan amount, interest rate and number of payments.';
    else if (loan <= 0 || loan > 1e10) msg = 'Enter a loan amount above $0.';
    else if (rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (n < 1 || n > 480 || n % 1 !== 0) msg = 'Enter 1 to 480 monthly payments.';
    else if (isNaN(start) || isNaN(first)) msg = 'Enter the funding date and the first payment date.';
    else if (first <= start) msg = 'The first payment must be due after the funding date.';
    else if (first - start > 366) msg = 'The first payment must be due within a year of funding.';
    else if (payRaw !== '' && (isNaN(payIn) || payIn <= 0 || payIn > 1e10)) msg = 'Enter a regular payment above $0, or leave it blank.';
    if (!msg) {
      ch = readChanges(n);
      msg = ch.error;
      if (!msg) {
        // Payment dates must stay in order.
        var prev = start;
        for (var k = 1; k <= n && !msg; k++) {
          var d = addMonths(first, k - 1) + (ch.changes[k] ? ch.changes[k].shift : 0);
          if (d <= prev) msg = 'Payment ' + k + ' would be made ' + (k === 1 ? 'on or before the funding date' : 'on or before payment ' + (k - 1)) + '. Change its days early or late.';
          prev = d;
        }
      }
    }
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { clear(); return; }

    var r = rate / 100;
    var pay = isNaN(payIn) ? levelPayment(loan, r, n, start, first, basis) : payIn;
    var base = simulate(loan, r, pay, n, start, first, basis, null);
    var yours = simulate(loan, r, pay, n, start, first, basis, ch.changes);
    last = { base: base, yours: yours };
    var diff = yours.interest - base.interest;
    setText('d35Payment', money.format(pay));
    setText('d35Diff', signed(diff));
    setText('d35Final', money.format(yours.finalPayment));
    setText('d35PerDiem', money.format(loan * r / 365));
    var s;
    if (ch.count === 0) s = 'No payments changed: paying every installment on its due date costs ' + money.format(base.interest) + ' in interest.';
    else if (diff > 0.005) s = 'Your payment dates and amounts add ' + money.format(diff) + ' of interest compared with paying on schedule.';
    else if (diff < -0.005) s = 'Your payment dates and amounts save ' + money.format(-diff) + ' of interest compared with paying on schedule.';
    else s = 'Your changes leave the total interest the same as paying on schedule.';
    s += ' The final payment of ' + money.format(yours.finalPayment) + ' is due ' + fmt(yours.finalDate) + ' and settles whatever is left';
    s += yours.count < n ? ', ' + (n - yours.count) + ' payment' + (n - yours.count === 1 ? '' : 's') + ' early.' : '.';
    if (!isNaN(payIn) && base.count === n && Math.abs(base.finalPayment - pay) > pay * 0.5)
      s += ' With your regular payment the on-schedule final payment is ' + money.format(base.finalPayment) + '.';
    setText('d35Summary', s);
    var rowsHtml = [
      ['Total interest', money.format(base.interest), money.format(yours.interest)],
      ['Final payment', money.format(base.finalPayment), money.format(yours.finalPayment)],
      ['Final payment date', fmt(base.finalDate), fmt(yours.finalDate)],
      ['Number of payments', String(base.count), String(yours.count)],
      ['Total paid', money.format(base.paid), money.format(yours.paid)]
    ];
    el('d35Compare').innerHTML = rowsHtml.map(function (x) {
      return '<tr><th scope="row">' + x[0] + '</th><td>' + x[1] + '</td><td>' + x[2] + '</td></tr>';
    }).join('');
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var startEl = el('d35Start'), firstEl = el('d35First');
    if (!startEl.value) {
      var t = new Date();
      startEl.value = iso(daysFromCivil(t.getFullYear(), t.getMonth() + 1, t.getDate()));
    }
    if (!firstEl.value) { var s = parseDate(startEl.value); if (!isNaN(s)) firstEl.value = iso(addMonths(s, 1)); }
    DEFAULT_ROWS.forEach(addRow);
    var form = el('d35Form');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('d35Add').addEventListener('click', function () {
      addRow({ n: '', shift: '', amount: '' });
      update();
    });
    el('d35View').addEventListener('change', renderSchedule);
    update();
  });
})();
